<?php require_once 'conexion.php';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$n=trim($_POST['nombre']??'');$u=trim($_POST['usuario']??'');$p=$_POST['password']??'';$tel=trim($_POST['telefono']??'');$correo=trim($_POST['correo']??'');$dir=trim($_POST['direccion']??'');if(!$n||!$u||strlen($p)<8)$error='Completa los campos. La contraseña debe tener al menos 8 caracteres.';else{try{$conexion->beginTransaction();$q=$conexion->prepare("INSERT INTO usuario(nombre,usuario,password,rol) VALUES(?,?,?,'cliente')");$q->execute([$n,$u,password_hash($p,PASSWORD_DEFAULT)]);$id=(int)$conexion->lastInsertId();$q=$conexion->prepare('INSERT INTO clientes(idUsuario,nombre,telefono,correo,direccion) VALUES(?,?,?,?,?)');$q->execute([$id,$n,$tel,$correo,$dir]);$conexion->commit();header('Location: login.php?registro=1');exit;}catch(Throwable $t){if($conexion->inTransaction())$conexion->rollBack();$error='No se pudo registrar. Verifica que el usuario no esté repetido.';}}} ?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="estilos.css"><link rel="stylesheet" href="sistema.css"><title>Registro de cliente</title></head><body class="login-body"><main class="login-card"><div class="logo-circle">🐾</div><h1>Crear cuenta de cliente</h1><?php if($error):?><div class="notice"><?=htmlspecialchars($error)?></div><?php endif;?><form method="post"><label>Nombre completo</label><input name="nombre" required><label>Usuario</label><input name="usuario" required><label>Contraseña (mínimo 8 caracteres)</label><input type="password" name="password" minlength="8" required><label>Teléfono</label><input name="telefono"><label>Correo</label><input type="email" name="correo"><label>Dirección</label><input name="direccion"><button class="btn full">Registrarme</button></form><a class="small-link" href="login.php">Ya tengo cuenta</a></main></body></html>